import thaumcraft.blocks.*;
import thaumcraft.entities.*;
import thaumcraft.registry.*;
import thaumcraft.items.CultistArmorItem;

/** Real native entities, block tickers, loot and saved data; original source constants as controls. */
final class OuterRuntimeVerification {
    private static final BlockPos POS=new BlockPos(3360,140,64);
    static void run(ServerLevel level,BiConsumer<Boolean,String> check)throws Exception {
        try {
        for(var entity:level.getEntitiesOfClass(net.minecraft.world.entity.Entity.class,new AABB(POS).inflate(40)))if(entity instanceof EldritchCrab||entity instanceof net.minecraft.world.entity.item.ItemEntity)entity.discard();
        level.getChunkAt(POS);for(var tile:List.of(R5Content.CARVED_STONE,R5Content.ANCIENT_RUNIC_STONE,R5Content.DECORATED_STONE,R5Content.ELDRITCH_DOOR_STONE)){var state=tile.get().defaultBlockState();level.setBlock(POS,state,2);check.accept(!state.isSolidRender(level,POS)&&state.getCollisionShape(level,POS).bounds().equals(new AABB(0,0,0,1,1,1)),"eldritch room stone is nonopaque with full gameplay collision: "+tile.getId());var drops=Block.getDrops(state,level,POS,null);if(tile==R5Content.CARVED_STONE)check.accept(drops.size()==1&&drops.getFirst().is(tile.get().asItem()),"carved stone drops itself");else if(tile==R5Content.ANCIENT_RUNIC_STONE)check.accept(drops.size()==1&&drops.getFirst().is(R3Equipment.KNOWLEDGE_FRAGMENT.get()),"metadata5 drops original resource9 knowledge fragment, not a shard");else check.accept(drops.isEmpty(),"decorated and door stone do not drop an item");}
        for(var block:List.of(R5Content.ELDRITCH_TRAP.get(),R5Content.CRAB_SPAWNER.get())){var state=block.defaultBlockState();level.setBlock(POS,state,2);check.accept(state.getDestroySpeed(level,POS)==15&&block.getExplosionResistance()==30,"original trap and crab vent hardness15 and blast resistance30");check.accept(state.getLightEmission(level,POS)==(block==R5Content.ELDRITCH_TRAP.get()?0:4),"original trap has no light; crab opening light4");check.accept(Block.getDrops(state,level,POS,level.getBlockEntity(POS)).isEmpty(),"trap and crab vent do not drop their creative/pick item");for(int i=0;i<20;i++){int xp=block.getExpDrop(state,level,POS,level.getBlockEntity(POS),null,ItemStack.EMPTY);check.accept(xp>=(block==R5Content.ELDRITCH_TRAP.get()?1:6)&&xp<=(block==R5Content.ELDRITCH_TRAP.get()?4:10),"original trap/vent XP interval "+i);}}
        for(var direction:Direction.values()){var pos=POS.offset(direction.ordinal()*3,3,0);var support=pos.relative(direction.getOpposite());level.setBlock(support,Blocks.STONE.defaultBlockState(),2);var state=R5Content.ANCIENT_CRYSTAL.get().defaultBlockState().setValue(AncientCrystalBlock.FACING,direction);level.setBlock(pos,state,2);check.accept(state.canSurvive(level,pos)&&level.getBlockEntity(pos) instanceof AncientCrystalBlockEntity,"ancient crystal has its own native tile for "+direction);var drops=Block.getDrops(state,level,pos,level.getBlockEntity(pos));check.accept(drops.size()==1&&drops.getFirst().is(R3Content.BALANCED_SHARD.get()),"ancient crystal drops original itemShard6 balanced shard");level.setBlockAndUpdate(support,Blocks.GLASS.defaultBlockState());check.accept(level.getBlockState(pos).is(R5Content.ANCIENT_CRYSTAL.get()),"existing ancient crystal only needs non-air support");level.setBlockAndUpdate(support,Blocks.AIR.defaultBlockState());check.accept(level.isEmptyBlock(pos),"removing support breaks ancient crystal for "+direction);}
        for(int mask=0;mask<64;mask++){boolean matches=true;for(int axis=0;axis<3;axis++){int low=switch(axis){case 0->4;case 1->0;default->2;},high=low+1;matches&=RoomStoneBounds.min(mask,axis)==((mask&(1<<low))!=0?.125f:0)&&RoomStoneBounds.max(mask,axis)==((mask&(1<<high))!=0?.875f:1);}check.accept(matches,"original independent face insets for neighbor mask "+mask);}
        for(var entry:R5Content.CULTIST_ARMOR.entrySet()){var armor=entry.getValue().get();var stack=new ItemStack(armor);boolean leader=armor.kind()==CultistArmorItem.Kind.LEADER,warping=armor.kind()==CultistArmorItem.Kind.ROBE||armor.kind()==CultistArmorItem.Kind.BOOTS;check.accept(stack.getMaxDamage()==armor.getType().getDurability(leader?40:15),"native slot durability retains original material multiplier: "+entry.getKey());check.accept(armor.isValidRepairItem(stack,new ItemStack(Items.IRON_INGOT))&&!armor.isValidRepairItem(stack,new ItemStack(Items.GOLD_INGOT)),"original iron repair ingredient: "+entry.getKey());check.accept(armor.getRunicCharge(stack)==0&&armor.getWarp(stack,null)==(warping?1:0)&&armor.getVisDiscount(stack,null,null)==(warping?1:0),"cultist runic, warp and vis interfaces: "+entry.getKey());}
        for(var armor:R5Content.CULTIST_ARMOR.values()){var item=armor.get();var expected=switch(item.kind()){case PLATE->Map.of("metallum",5,"alienis",1);case ROBE->Map.of("metallum",3,"pannus",2,"alienis",1);case LEADER->Map.of("metallum",5,"alienis",2);case BOOTS->Map.of("metallum",4,"alienis",1);};check.accept(thaumcraft.data.ThaumcraftData.aspects(level.getServer(),new ItemStack(item)).equals(expected),"original cultist equipment aspects loaded through native server data: "+armor.getId());}check.accept(thaumcraft.data.ThaumcraftData.aspects(level.getServer(),new ItemStack(R5Content.RUNIC_KEY.get())).equals(Map.of("vinculum",4,"cognitio",4,"machina",4)),"original runed tablet aspects loaded through native server data");
        var crab=R5Entities.CRAB.get().create(level);check.accept(crab.getMaxHealth()==20&&crab.getAttributeValue(Attributes.ATTACK_DAMAGE)==4&&crab.getAttributeValue(Attributes.MOVEMENT_SPEED)==.3,"original crab initialization attributes");crab.setHelm(true);check.accept(crab.getArmorValue()==5&&!crab.canBeAffected(new MobEffectInstance(MobEffects.POISON,100)),"helmet armor and poison immunity");var tag=new CompoundTag();crab.addAdditionalSaveData(tag);var copy=R5Entities.CRAB.get().create(level);copy.readAdditionalSaveData(tag);check.accept(copy.hasHelm()&&copy.getArmorValue()==5,"helmet flag persists through native entity NBT");copy.setHelm(false);check.accept(copy.getArmorValue()==0&&copy.isAlliedTo(crab),"unarmored crab defense and crab alliance");
        crab.moveTo(POS.getCenter().add(0,2,5));crab.hurt(level.damageSources().generic(),100);check.accept(!crab.hasHelm(),"fatal damage also releases original helmet armor");check.accept(level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(POS).inflate(8)).stream().anyMatch(item->item.getItem().is(R5Content.CULTIST_ARMOR.get("cultist_plate_chestplate").get())),"shell loss drops a real cultist plate chestplate");
        var rider=R5Entities.CRAB.get().create(level);var victim=new net.minecraft.world.entity.animal.Cow(EntityType.COW,level);victim.moveTo(POS.getCenter().add(0,3,0));rider.setHelm(false);rider.moveTo(victim.position().add(0,1,0));rider.setTarget(victim);float victimHealth=victim.getHealth();rider.tick();check.accept(rider.isPassenger()&&rider.getVehicle()==victim,"unarmored airborne crab attaches to its nearby living target");check.accept(victim.getHealth()==victimHealth-4&&rider.getVehicleAttachmentPoint(victim).equals(new Vec3(0,-.5,0)),"mounted crab applies its original attack damage and rider height");rider.stopRiding();rider.discard();victim.discard();
        var player=new FakePlayer(level,new GameProfile(UUID.fromString("ae6c9bc8-6f3e-4f3e-9bab-08e287a30005"),"OuterRoomQA")){@Override public boolean isInvulnerableTo(net.minecraft.world.damagesource.DamageSource source){return false;}};var immunity=net.minecraft.server.level.ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");immunity.setAccessible(true);immunity.setInt(player,0);player.setGameMode(GameType.SURVIVAL);player.moveTo(POS.getCenter().add(1,0,0));level.players().add(player);
        try {level.setBlock(POS,R5Content.ELDRITCH_TRAP.get().defaultBlockState(),2);var trap=(EldritchTrapBlockEntity)level.getBlockEntity(POS);float health=player.getHealth();for(int i=0;i<20;i++)trap.serverTick();check.accept(trap.countdown()==0&&player.getHealth()==health,"trap first twenty ticks are harmless");var control=new Random(123);int delay=10+control.nextInt(25);boolean addsWarp=control.nextBoolean();int warp=addsWarp?1+control.nextInt(2):0;int before=thaumcraft.knowledge.KnowledgeService.get(player).temporaryWarp();level.random.setSeed(123);trap.serverTick();check.accept(trap.countdown()==delay&&player.getHealth()==health-2,"twenty-first trap tick applies two magic damage and original seeded delay");check.accept(thaumcraft.knowledge.KnowledgeService.get(player).temporaryWarp()==before+warp,"original seeded temporary warp amount");var snapshot=trap.saveWithFullMetadata(level.registryAccess());var loaded=new EldritchTrapBlockEntity(POS,trap.getBlockState());loaded.loadWithComponents(snapshot,level.registryAccess());check.accept(loaded.countdown()==20,"trap countdown resets on NBT load as in TC4");
            for(var face:Direction.values()){var spawnerPos=POS.offset(0,8,face.ordinal()*4);level.removeBlock(spawnerPos,false);level.setBlock(spawnerPos,R5Content.CRAB_SPAWNER.get().defaultBlockState().setValue(EldritchCrabSpawnerBlock.FACING,face),2);var spawner=(EldritchCrabSpawnerBlockEntity)level.getBlockEntity(spawnerPos);player.moveTo(spawnerPos.getCenter().add(2,0,0));check.accept(spawner.activated()&&!spawner.crowded(),"spawner activates near a player: "+face);check.accept(spawner.getBlockState().triggerEvent(level,spawnerPos,1,0)&&spawner.venting()==20,"block event reaches the native vent tile: "+face);for(int i=0;i<150;i++)spawner.tick();var spawned=level.getEntitiesOfClass(EldritchCrab.class,new AABB(spawnerPos).inflate(2));check.accept(spawned.size()==1&&!spawned.getFirst().hasHelm(),"spawner produces a real unarmored eldritch crab: "+face);var entity=spawned.getFirst();check.accept(entity.position().equals(spawnerPos.relative(face).getCenter())&&entity.getDeltaMovement().distanceTo(new Vec3(face.getStepX()*.2f,face.getStepY()*.2f,face.getStepZ()*.2f))<1e-8,"original spawn offset and launch velocity: "+face);entity.discard();level.removeBlock(spawnerPos,false);}
        }finally{level.players().remove(player);}
        var cycle=new thaumcraft.world.dim.BossCycleData();var rng=net.minecraft.util.RandomSource.create(4321);var control=new Random(4321);int counter=0;for(int i=0;i<64;i++){counter++;if(control.nextFloat()<.25f)counter++;check.accept(cycle.next(rng)==counter%4&&cycle.count()==counter,"original boss counter extra-increment ordering "+i);}var restored=thaumcraft.world.dim.BossCycleData.load(cycle.save(new CompoundTag(),level.registryAccess()),level.registryAccess());check.accept(restored.count()==counter&&cycle.isDirty(),"world boss counter NBT and dirty tracking");
        for(int sign:new int[]{1,-1}){var p=new BlockPos(sign*3370,146,sign*80);level.getChunkAt(p);for(int x=-2;x<=2;x++)for(int y=-1;y<=3;y++)for(int z=-2;z<=2;z++)level.setBlock(p.offset(x,y,z),Blocks.AIR.defaultBlockState(),2);var passenger=R5Entities.CRAB.get().create(level);var mount=new net.minecraft.world.entity.animal.Cow(EntityType.COW,level);passenger.moveTo(p.getCenter().add(0,-.5,0));mount.moveTo(p.getCenter().add(0,-.5,0));check.accept(LegacyRiderPosition.choose(passenger,mount).equals(mount.position().add(0,mount.getBbHeight(),0)),"old relocation defaults to vehicle top in open air: "+sign);for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<1;dz++){if(dx==0&&dz==0)continue;var sample=new BlockPos((int)(passenger.getX()+dx),(int)passenger.getY()-1,(int)(passenger.getZ()+dz));level.setBlock(sample,Blocks.STONE.defaultBlockState(),2);}check.accept(LegacyRiderPosition.choose(passenger,mount).equals(passenger.position().add(1,1,0)),"old relocation keeps last safe lower-support candidate; dz excludes+1 and negative coordinates truncate: "+sign);var first=new BlockPos((int)(passenger.getX()-1),(int)passenger.getY(),(int)(passenger.getZ()-1));level.setBlock(first,Blocks.STONE.defaultBlockState(),2);check.accept(LegacyRiderPosition.choose(passenger,mount).equals(passenger.position().add(-1,1,-1)),"old relocation returns immediately for first safe current-height support: "+sign);level.setBlock(BlockPos.containing(passenger.position().add(-1,1,-1)),Blocks.STONE.defaultBlockState(),2);check.accept(!LegacyRiderPosition.choose(passenger,mount).equals(passenger.position().add(-1,1,-1)),"old relocation skips blocked rider bounding box: "+sign);passenger.startRiding(mount,true);LegacyRiderPosition.choose(passenger,mount);check.accept(passenger.getVehicle()==mount,"position selection preserves riding relationship: "+sign);passenger.stopRiding();passenger.discard();mount.discard();}
        var savedCycle=thaumcraft.world.dim.BossCycleData.get(level);var savedRng=net.minecraft.util.RandomSource.create(777);for(int i=0;i<12;i++)savedCycle.next(savedRng);check.accept(savedCycle==thaumcraft.world.dim.BossCycleData.get(level.getServer().getLevel(Level.NETHER)),"boss counter belongs to the owning world across native dimensions");java.nio.file.Files.writeString(java.nio.file.Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/full_port/outer-reload-control.json"),"{\"bossCount\":"+savedCycle.count()+"}\n");
        for(var face:Direction.values()){var fixture=POS.offset(24,6,face.ordinal()*3);level.setBlock(fixture,R5Content.CRAB_SPAWNER.get().defaultBlockState().setValue(EldritchCrabSpawnerBlock.FACING,face),2);var timer=EldritchCrabSpawnerBlockEntity.class.getDeclaredField("count");timer.setAccessible(true);timer.setInt(level.getBlockEntity(fixture),700);}
        }finally{releaseChunks(level);}
    }
    static void prepare(ServerLevel level){for(int x=-2;x<=2;x++)for(int z=-2;z<=3;z++){int cx=(POS.getX()>>4)+x,cz=(POS.getZ()>>4)+z;level.setChunkForced(cx,cz,true);level.getChunk(cx,cz);}}
    static boolean ready(ServerLevel level){for(int x=-2;x<=2;x++)for(int z=-2;z<=3;z++)if(!level.areEntitiesLoaded(ChunkPos.asLong((POS.getX()>>4)+x,(POS.getZ()>>4)+z)))return false;return true;}
    static void releaseChunks(ServerLevel level){for(int x=-2;x<=2;x++)for(int z=-2;z<=3;z++)level.setChunkForced((POS.getX()>>4)+x,(POS.getZ()>>4)+z,false);}
    static void reload(ServerLevel level,BiConsumer<Boolean,String> check)throws Exception {try{var control=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(java.nio.file.Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/full_port/outer-reload-control.json"))).getAsJsonObject();check.accept(thaumcraft.world.dim.BossCycleData.get(level).count()==control.get("bossCount").getAsInt(),"boss counter survives a real dedicated-server restart");for(var face:Direction.values()){var pos=POS.offset(24,6,face.ordinal()*3);var state=level.getBlockState(pos);check.accept(state.is(R5Content.CRAB_SPAWNER.get())&&state.getValue(EldritchCrabSpawnerBlock.FACING)==face,"native spawner orientation survives restart: "+face);var tile=(EldritchCrabSpawnerBlockEntity)level.getBlockEntity(pos);check.accept(tile.countdown()<=150&&tile.countdown()>0&&tile.venting()==0,"spawner resets unsaved timer700 and vent state on actual restart: "+face);}}finally{releaseChunks(level);}}
    private OuterRuntimeVerification(){}
}
